/* ---------- adaptive onboarding: the step list is computed from the answers ---------- */
function steps(){
 const o=S.o,a=['name','about','measure','goal'];
 if(o.goal==='LOSE'||o.goal==='GAIN')a.push('pace');
 a.push('activity');
 if(o.goal==='MUSCLE')a.push('training');
 if(o.goal==='MUSCLE'||o.act==='HIGH'||o.act==='ATHLETE')a.push('protein');
 a.push('care','allergy','safety','rhythm');
 if(o.care.includes('HEART_DISEASE'))a.push('fluid');
 a.push('result');return a;
}
const adapt=(why)=>`<div class="adapt">${E('sparkles',14)}${L('سؤال خاص بك','Just for you')} · ${why}</div>`;
function opt(act,v,on,emo,t,d,extra=''){return `<button class="opt press" data-act="${act}" data-v="${v}" aria-pressed="${on}"><span class="emobox" style="--tc:var(--brand)">${E(emo,30)}</span><span class="grow"><span class="t" style="display:block">${t}</span>${d?`<span class="d">${d}</span>`:''}</span>${extra}<span class="radio">${I('check','',3)}</span></button>`}
function wheel(key,min,max,step,unit,label){
 let it='';for(let v=min;v<=max+1e-9;v+=step)it+=`<div class="it" data-v="${+v.toFixed(2)}">${fmt(v,step<1?1:0)}${unit?' '+unit:''}</div>`;
 return `<div class="wheelbox">${label?`<div class="wlabel">${label}</div>`:''}<div class="wheel" data-wheel="${key}" data-min="${min}" data-step="${step}" tabindex="0" aria-label="${label||key}"><div class="pad"></div>${it}<div class="pad"></div></div></div>`;
}
function bmiCard(){
 const b=S.o.w/((S.o.h/100)**2),pos=Math.min(1,Math.max(0,(b-15)/(40-15)));
 const [lab,col]=b<18.5?[L('أقل من الطبيعي','Below normal'),'var(--carb)']:b<25?[L('طبيعي','Normal'),'var(--ok)']:b<30?[L('فوق الطبيعي','Above normal'),'var(--part)']:[L('مرتفع','High'),'var(--warn)'];
 return `<div class="between"><div class="row" style="gap:8px"><span class="num" style="font-size:30px;font-weight:700" id="bmiv">${fmt(b,1)}</span><span class="muted">${L('مؤشر كتلة الجسم','Body mass index')}</span></div><span class="badge" id="bmil" style="background:color-mix(in srgb,${col} 18%,transparent);color:${col}">${lab}</span></div>
 <div style="position:relative;margin-top:12px;direction:ltr"><div style="height:10px;border-radius:9px;background:linear-gradient(90deg,var(--carb) 0 14%,var(--ok) 14% 40%,var(--part) 40% 60%,var(--warn) 60%)"></div>
 <i id="bmim" style="position:absolute;top:-5px;left:calc(${pos*100}% - 10px);width:20px;height:20px;border-radius:50%;background:var(--surface);border:4px solid ${col};transition:left .3s,border-color .3s"></i>
 <div class="between num" style="font-size:11px;color:var(--fg-3);margin-top:6px"><span>15</span><span>18.5</span><span>25</span><span>30</span><span>40</span></div></div>`;
}
function paceInfo(){
 const o=S.o,diff=Math.abs(o.w-o.tw),r=o.goal==='GAIN'?Math.min(o.rate,0.5):Math.min(o.rate,o.w*0.01),wk=Math.ceil(diff/r);
 const d=new Date(2026,9,13+wk*7);const mon=L(['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'],['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])[d.getMonth()];
 return `${E('spiral-calendar',22)}<span>${L(G('تصل إلى','تصلين إلى'),'You reach')} <b class="num">${fmt(o.tw)} ${L('كغ','kg')}</b> ${L('بعد نحو','in about')} <b class="num">${fmt(wk)}</b> ${L('أسبوعًا، تقريبًا في','weeks, around')} <b>${mon} ${d.getFullYear()}</b></span>`;
}
